import React from 'react'
import { formatDisplayDate } from '../adapters/forecastDate'
import { compassPoint } from '../adapters/spatialTimelineView'

const FEATURES = {
  mean_temperature_2m: 'Mean temperature',
  mean_relative_humidity_2m: 'Mean humidity',
  precipitation_accumulation: 'Accumulated rainfall',
  mean_wind_speed: 'Mean wind speed',
  vector_mean_wind_direction_from: 'Wind from',
  directional_persistence: 'Wind persistence',
}

/** Actual backend observations only. No weather field, interpolation or
 * future measurements are generated by the frontend. */
export default function Era5Observations({ state, asOf, district, unavailableText = null }) {
  return <div className="flex flex-col gap-1.5 text-[10.5px]" aria-label="Environmental observations">
    <div className="font-semibold text-on-surface">ERA5 · {district ?? 'Authorised district'}{asOf ? ` · context before ${formatDisplayDate(asOf)}` : ''}</div>
    <div className="text-[9.5px] text-amber-200">Historical observations · display only · not used in C0 spatial scores</div>
    {unavailableText ? <p className="text-amber-200">{unavailableText}</p> : <>
      {state?.status === 'loading' && <p role="status">Retrieving observations for this date and district…</p>}
      {state?.status === 'error' && <p className="text-amber-200">ERA5 observations unavailable (provider or network). No values are substituted.</p>}
      {(state?.data?.observations ?? []).map((observation, index) => {
        const grid = observation.grid_cell ?? {}
        const window = observation.window ?? {}
        return <div key={`${observation.role}:${grid.latitude}:${grid.longitude}:${index}`} className="rounded-md border border-outline-variant/20 bg-surface-container-lowest/30 p-2" aria-label="ERA5 observations">
          <div className="font-semibold text-on-surface">{observation.role === 'DISTRICT_REFERENCE_POINT' ? `${observation.district ?? district} district reference` : 'Eligible source location'}</div>
          <div className="text-[9px] text-on-surface-variant/65">Source cell: {Number.isFinite(grid.latitude) ? grid.latitude.toFixed(2) : '—'}, {Number.isFinite(grid.longitude) ? grid.longitude.toFixed(2) : '—'}</div>
          {observation.status !== 'OK' ? <p>{observation.status ?? 'No observation available'}</p> : <>
            <div className="text-[9px] text-on-surface-variant/65">{window.number_of_hourly_samples ?? '—'} hourly samples · {window.window_start ?? '—'} → {window.window_end ?? '—'}</div>
            <dl className="mt-1 grid grid-cols-1 gap-1 sm:grid-cols-2">{(observation.features ?? []).filter((feature) => FEATURES[feature.feature_name]).map((feature) => <div key={feature.feature_name} className="flex justify-between gap-2" title={feature.analysis_method}>
              <dt>{FEATURES[feature.feature_name]}</dt><dd className="shrink-0 font-mono text-on-surface">{feature.status === 'REAL' && Number.isFinite(feature.value) ? `${feature.value.toFixed(feature.units === 'ratio' ? 2 : 1)} ${feature.units ?? ''}${feature.feature_name === 'vector_mean_wind_direction_from' ? ` · ${compassPoint(feature.value)}` : ''}` : feature.status ?? 'Missing'}</dd>
            </div>)}</dl>
          </>}
        </div>
      })}
      {state?.status === 'ready' && !(state.data?.observations?.length > 0) && <p>No environmental observations returned for this date and location.</p>}
      {state?.data && <p className="text-[9px] text-on-surface-variant/60">{state.data.model ?? 'Reanalysis'} · {typeof state.data.provider === 'string' ? state.data.provider : 'Provider not reported'}. This is neither live weather nor a weather forecast; no disease-movement inference is made.</p>}
    </>}
  </div>
}
